<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CONFLICT (actor_id, operation, request_key) DO NOTHING</span></span>
